+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("month and weekday names, any case", () => {
+  expect(nextRun("0 12 * jan-mar mon", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-05T12:00:00.000Z");
+  expect(nextRun("0 0 1 DEC *", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-12-01T00:00:00.000Z");
+});
+
+test("steps on a single value run to the end of the field", () => {
+  expect(nextRun("5/20 * * * *", at("2026-01-01T00:05:00Z")).toISOString()).toBe("2026-01-01T00:25:00.000Z");
+  expect(nextRun("*/15 * * * *", at("2026-01-01T00:31:00Z")).toISOString()).toBe("2026-01-01T00:45:00.000Z");
+  expect(nextRun("10-30/10 * * * *", at("2026-01-01T00:20:00Z")).toISOString()).toBe("2026-01-01T00:30:00.000Z");
+});
+
+test("Sunday as 7", () => {
+  expect(nextRun("0 0 * * 7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+  expect(nextRun("0 0 * * 5-7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-02T00:00:00.000Z");
+  expect(nextRun("0 0 * * 0-7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-02T00:00:00.000Z");
+});
+
+test("day of month and day of week both restricted: either matches", () => {
+  expect(nextRun("0 0 1,15 * 1", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+  expect(nextRun("0 0 13 * 1", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-05T00:00:00.000Z");
+});
+
+test("a full range in one day field leaves the other to decide", () => {
+  expect(nextRun("0 0 13 * 1-7", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-13T00:00:00.000Z");
+  expect(nextRun("0 0 * * 0-6", at("2026-01-02T00:00:00Z")).toISOString()).toBe("2026-01-03T00:00:00.000Z");
+});
+
+test("29 February", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-03-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+  expect(nextRun("0 0 29 2 *", at("2096-03-01T00:00:00Z")).toISOString()).toBe("2104-02-29T00:00:00.000Z");
+});
+
+test("invalid expressions throw", () => {
+  const now = at("2026-01-01T00:00:00Z");
+  for (const bad of ["0 0 * * 1-", "*/0 * * * *", "*/x * * * *", "1.5 * * * *", "5-10-20 * * * *", "30-10 * * * *",
+    "0 0 * FOO *", "0 0 * * MOXX", "60 * * * *", "0 0 0 * *", "0 0 * 13 *", "0 0 * * 8", "0 0 30 2 *", "0 0 * * 1/-2",
+    "JAN * * * *", "0 0 * * 1,,2", "-5 * * * *"]) {
+    expect(() => nextRun(bad, now), bad).toThrow(RangeError);
+  }
+});
