diff -ruN '--exclude=node_modules' '--exclude=.git' a/semver.regress.test.ts b/semver.regress.test.ts
--- a/semver.regress.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/semver.regress.test.ts	2026-10-28 06:46:39.602933208 +0000
@@ -0,0 +1,56 @@
+import { expect, test } from "bun:test";
+import { satisfies } from "./semver";
+
+test("caret on 0.x follows the left-most non-zero part", () => {
+  expect(satisfies("0.2.5", "^0.2.3")).toBe(true);
+  expect(satisfies("0.3.0", "^0.2.3")).toBe(false);
+  expect(satisfies("0.0.3", "^0.0.3")).toBe(true);
+  expect(satisfies("0.0.4", "^0.0.3")).toBe(false);
+  expect(satisfies("0.9.0", "^0.x")).toBe(true);
+  expect(satisfies("1.0.0", "^0.0")).toBe(false);
+  expect(satisfies("0.0.9", "^0.0")).toBe(true);
+});
+
+test("partial versions are X-ranges", () => {
+  expect(satisfies("1.2.9", "1.2")).toBe(true);
+  expect(satisfies("1.3.0", "1.2")).toBe(false);
+  expect(satisfies("1.9.0", "1.x")).toBe(true);
+  expect(satisfies("2.0.0", "1.x")).toBe(false);
+  expect(satisfies("1.0.0", "1.2.3")).toBe(false);
+});
+
+test("partial versions with an operator", () => {
+  expect(satisfies("2.0.0", "> 1")).toBe(true);
+  expect(satisfies("1.5.0", ">1.2")).toBe(true);
+  expect(satisfies("1.2.0", "<1.2")).toBe(false);
+  expect(satisfies("1.9.0", "<=1.2")).toBe(false);
+  expect(satisfies("1.2.0", ">= 1.2")).toBe(true);
+  expect(satisfies("10.0.0", "<=10")).toBe(true);
+  expect(satisfies("1.0.0", ">*")).toBe(false);
+});
+
+test("hyphen ranges", () => {
+  expect(satisfies("1.2.5", "1.2.3 - 2.3")).toBe(true);
+  expect(satisfies("2.3.9", "1.2.3 - 2.3")).toBe(true);
+  expect(satisfies("2.4.0", "1.2.3 - 2.3")).toBe(false);
+  expect(satisfies("1.2.5", "1.2 - 2.3.4")).toBe(true);
+  expect(satisfies("1.2.2", "1.2.3 - 2")).toBe(false);
+});
+
+test("prerelease needs a prerelease comparator on the same version", () => {
+  expect(satisfies("1.2.3-beta.4", ">=1.2.3-alpha")).toBe(true);
+  expect(satisfies("3.4.5-beta", ">=1.2.3-alpha")).toBe(false);
+  expect(satisfies("2.0.0-beta", "*")).toBe(false);
+  expect(satisfies("2.0.0-alpha", "<2.0.0-0")).toBe(false);
+});
+
+test("prerelease identifiers compare numerically when numeric", () => {
+  expect(satisfies("1.0.0-beta.10", ">1.0.0-beta.9")).toBe(true);
+  expect(satisfies("1.0.0-beta.9", "<1.0.0-beta.10")).toBe(true);
+});
+
+test("leading zeros and empty prerelease are not versions", () => {
+  expect(satisfies("01.2.3", "*")).toBe(false);
+  expect(satisfies("1.2.3-01", "*")).toBe(false);
+  expect(satisfies("1.2.3", "1.2.3-")).toBe(false);
+});
